    army(W, group, 0.0, 29.3, 11, { shields: [0x8c784e, 0x6b5b3b, 0x8a7a2a, 0x3a5a8a] });

    /* hero: the water — a focal stone in the flow */
    rock(W, group, 0, 0, 11, 1.7, 0x6b5b3b);

    /* figures */
    person(W, group, [-5, 0, 16], { robe: 0x8a6a44, head: 'wrap', wrap: 0xf8d48a, wrapTrim: 0x978154, beard: 'long', staff: 'planted', ry: -0.18, s: 1.04 });
    person(W, group, [4.5, 0, 17], { robe: 0x8a6a44, head: 'wrap', wrap: 0xf8d48a, wrapTrim: 0x978154, beard: 'long', staff: 'planted', ry: -0.05, s: 1.08 });

    return W.finish();
